cd multicode/duckpit/build/par3/rw-U/Assets/Game/Code/OnePit; python3 -I - <<'EOF'
p='Prod/RoomUpgrades.cs'
s=open(p,encoding='utf-8').read()
a=s.index('        /// Сейв до 02.11 (в op.room нет')
b=s.index('        /// «Скинуть» открыта: куплена (или старый сейв).')
b2=s.index('\n',s.index('public static bool DropBought',b))+1
new='''        /// Сейв до 02.11 (в op.room нет «drop_all»), где кнопки уже были (бит FThrow в op.ux или глава II): обе кнопки остаются — при старте
        /// зала им выдаются купленные уровни (MigrateButtons). Ничего не отнимаем.
        static bool _dropMissing = true, _restoredOnce;
        /// «Кинуть» открыта: куплен 1-й уровень «Дальности».
        public static bool ThrowBought => L(RThrow) > 0;
        /// «Скинуть» открыта: куплена.
        public static bool DropBought => L(RDrop) > 0;
        static void MigrateButtons()
        {
            if (!_dropMissing || !_restoredOnce || !OnePitBalance.FlowV3 || RThrow < 0 || RDrop < 0) return;
            _dropMissing = false;
            if ((HallUx.Flags & HallUx.FThrow) == 0 && OnePitState.Chapter < 2) return;
            if (_lv[RThrow] == 0) _lv[RThrow] = 1;
            _lv[RDrop] = 1;
            Debug.Log("[PITT] [onepit] room upg migrate buttons: throw lv=" + _lv[RThrow] + " drop lv=1 (сейв до 02.11)");
        }
'''
s=s[:a]+new+s[b2:]
s=s.replace('''            _comboTimeMissing = true;
            _restored = false;
            int n = 0;''','''            _comboTimeMissing = true;
            if (catchUp) MigrateButtons();
            _restored = false;
            int n = 0;''')
open(p,'w',encoding='utf-8').write(s)
EOF
