        /// к герою станок (он в кадре; дальний — со второго): из станков дальше GremIntroMinD м от героя — ближайший, иначе ближайший вообще.
        static bool PickTarget(out Tgt best, bool nearest = false)
        {'''
assert old in s
s=s.replace(old,new)
old='''            var hero = HeroPos;
            float bd = -1f;
            for (int i = 0; i < _tg.Count; i++)
            {
                var t = _tg[i];
                if (Busy(t.Id)) continue;
                float d = Ext.FlatDist(hero, t.Pos);
                if (d > bd) { bd = d; best = t; }
            }
            return bd >= 0f;
        }
'''
new='''            var hero = HeroPos;
            if (nearest)
            {
                float nd = float.MaxValue, fd = float.MaxValue;
                Tgt far = default;
                bool any = false, anyFar = false;
                for (int i = 0; i < _tg.Count; i++)
                {
                    var t = _tg[i];
                    if (Busy(t.Id)) continue;
                    float d = Ext.FlatDist(hero, t.Pos);
                    any = true;
                    if (d < nd) { nd = d; best = t; }
                    if (d >= OnePitBalance.GremIntroMinD && d < fd) { fd = d; far = t; anyFar = true; }
                }
